package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var n, m int
	var mod int64
	fmt.Fscan(in, &n, &m, &mod)

	fact := make([]int64, m+1)
	invFact := make([]int64, m+1)
	fact[0] = 1
	for i := 1; i <= m; i++ {
		fact[i] = fact[i-1] * int64(i) % mod
	}

	powMod := func(a, e int64) int64 {
		result := int64(1)
		for e > 0 {
			if e&1 == 1 {
				result = result * a % mod
			}
			a = a * a % mod
			e >>= 1
		}
		return result
	}

	invFact[m] = powMod(fact[m], mod-2)
	for i := m; i > 0; i-- {
		invFact[i-1] = invFact[i] * int64(i) % mod
	}

	f := make([]int64, m+1)
	g := make([]int64, m+1)
	f[0] = 1

	for k := 1; k <= m; k++ {
		var sumF, sumG int64

		for i := 0; i < k; i++ {
			j := k - 1 - i

			comb := fact[k-1] * invFact[i] % mod
			comb = comb * invFact[j] % mod

			base := f[i] * f[j] % mod
			sumF = (sumF + comb*base) % mod

			previousCost := (g[i]*f[j] + f[i]*g[j]) % mod
			term := previousCost * int64(k+1) % mod

			immediateCost := (int64(i*(i+1)/2) + int64(j*(j+1)/2)) % mod
			term = (term + base*immediateCost) % mod

			sumG = (sumG + comb*term) % mod
		}

		f[k] = sumF * int64(k+1) % mod
		g[k] = sumG
	}

	h := make([]int64, m+1)
	jSeries := make([]int64, m+1)
	h[0] = 1
	for k := 1; k <= m; k++ {
		h[k] = f[k] * invFact[k] % mod
		jSeries[k] = g[k] * invFact[k] % mod
	}

	multiply := func(a, b []int64) []int64 {
		c := make([]int64, m+1)
		for i := 0; i <= m; i++ {
			if a[i] == 0 {
				continue
			}
			for j := 0; i+j <= m; j++ {
				if b[j] == 0 {
					continue
				}
				c[i+j] = (c[i+j] + a[i]*b[j]) % mod
			}
		}
		return c
	}

	q := n - m + 1
	exponent := q - 1
	resultPoly := make([]int64, m+1)
	resultPoly[0] = 1
	basePoly := h

	for exponent > 0 {
		if exponent&1 == 1 {
			resultPoly = multiply(resultPoly, basePoly)
		}
		exponent >>= 1
		if exponent > 0 {
			basePoly = multiply(basePoly, basePoly)
		}
	}

	var coefficient int64
	for k := 1; k <= m; k++ {
		coefficient = (coefficient + jSeries[k]*resultPoly[m-k]) % mod
	}

	answer := fact[m] * int64(q) % mod
	answer = answer * coefficient % mod

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, answer)
	out.Flush()
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var n, m int
	var mod int64
	fmt.Fscan(in, &n, &m, &mod)

	mul := func(a, b int64) int64 {
		return a * b % mod
	}

	inv := make([]int64, m+1)
	if m >= 1 {
		inv[1] = 1
	}
	for i := 2; i <= m; i++ {
		inv[i] = (mod - mul(mod/int64(i), inv[int(mod%int64(i))])) % mod
	}

	tri := make([]int64, m+1)
	for i := 0; i <= m; i++ {
		tri[i] = int64(i*(i+1)/2) % mod
	}

	// A[k] is the normalized weighted count for filling one block of length k.
	// E[k] is the corresponding normalized total madness.
	A := make([]int64, m+1)
	E := make([]int64, m+1)
	A[0] = 1

	for k := 1; k <= m; k++ {
		var sumA, sumE int64

		for l := 0; l < k; l++ {
			r := k - 1 - l

			prod := mul(A[l], A[r])
			sumA += prod
			if sumA >= mod {
				sumA -= mod
			}

			existing := (mul(E[l], A[r]) + mul(A[l], E[r])) % mod
			term := mul(int64(k+1), existing)

			lastMadness := (tri[l] + tri[r]) % mod
			term += mul(prod, lastMadness)
			term %= mod

			sumE += term
			if sumE >= mod {
				sumE -= mod
			}
		}

		A[k] = mul(mul(sumA, int64(k+1)), inv[k])
		E[k] = mul(sumE, inv[k])
	}

	// Compute G(x) = (1 + A[1]x + A[2]x^2 + ... )^(n-m).
	exponent := n - m
	G := make([]int64, m+1)
	G[0] = 1

	for k := 1; k <= m; k++ {
		var sum int64
		for i := 1; i <= k; i++ {
			coef := int64(exponent+1)*int64(i) - int64(k)
			coef %= mod
			if coef < 0 {
				coef += mod
			}

			term := mul(mul(coef, A[i]), G[k-i])
			sum += term
			if sum >= mod {
				sum -= mod
			}
		}
		G[k] = mul(sum, inv[k])
	}

	var coefficient int64
	for k := 1; k <= m; k++ {
		coefficient += mul(E[k], G[m-k])
		if coefficient >= mod {
			coefficient -= mod
		}
	}

	factorial := int64(1)
	for i := 2; i <= m; i++ {
		factorial = mul(factorial, int64(i))
	}

	answer := mul(coefficient, int64(n-m+1))
	answer = mul(answer, factorial)

	fmt.Fprintln(out, answer)
}

