	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var n, m int
	var mod int64
	fmt.Fscan(in, &n, &m, &mod)

	inv := make([]int64, m+1)
	inv[1] = 1
	for i := 2; i <= m; i++ {
		x := int64(i)
		inv[i] = (mod - (mod/x)*inv[mod%x]%mod) % mod
	}

	f := make([]int64, m+1)
	g := make([]int64, m+1)
	f[0] = 1

	for k := 1; k <= m; k++ {
		var sumF, sumG int64

		for x := 0; x < k; x++ {
			y := k - 1 - x

			prod := f[x] * f[y] % mod
			sumF += prod
			if sumF >= mod {
				sumF -= mod
			}

			previous := (g[x]*f[y] + f[x]*g[y]) % mod
			distance := int64(x*(x+1)/2 + y*(y+1)/2)

			term := int64(k+1) * previous % mod
			term = (term + distance%mod*prod) % mod

			sumG += term
			if sumG >= mod {
				sumG -= mod
			}
		}

		f[k] = int64(k+1) * sumF % mod * inv[k] % mod
		g[k] = sumG * inv[k] % mod
	}

	q := n - m + 1
	h := make([]int64, m+1)
	h[0] = 1

	for degree := 1; degree <= m; degree++ {
		var sum int64

		for k := 1; k <= degree; k++ {
			coef := int64(q*k - degree)
			coef %= mod
			if coef < 0 {
				coef += mod
			}

			term := coef * f[k] % mod
			term = term * h[degree-k] % mod

			sum += term
			if sum >= mod {
				sum -= mod
			}
		}

		h[degree] = sum * inv[degree] % mod
	}

	var coefficient int64
	for k := 1; k <= m; k++ {
		coefficient += g[k] * h[m-k] % mod
		if coefficient >= mod {
			coefficient -= mod
		}
	}

	factorial := int64(1)
	for i := 2; i <= m; i++ {
		factorial = factorial * int64(i) % mod
	}

	answer := coefficient * int64(q) % mod
	answer = answer * factorial % mod

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var mod int64

func modPow(a, e int64) int64 {
	res := int64(1)
	a %= mod
	for e > 0 {
		if e&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return res
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n, m int
	fmt.Fscan(in, &n, &m, &mod)

	inv := make([]int64, m+1)
	invFact := make([]int64, m+1)
	fact := make([]int64, m+1)

	fact[0] = 1
	invFact[0] = 1
	if m >= 1 {
		inv[1] = 1
	}

	for i := 1; i <= m; i++ {
		if i > 1 {
			r := int(mod % int64(i))
			inv[i] = (mod - (mod/int64(i))*inv[r]%mod) % mod
		}
		fact[i] = fact[i-1] * int64(i) % mod
		invFact[i] = invFact[i-1] * inv[i] % mod
	}

	tri := make([]int64, m+1)
	for i := 0; i <= m; i++ {
		tri[i] = int64(i*(i+1)/2) % mod
	}

	// f[k] = F_k / k!, where F_k is the total transition weight
	// of a single occupied component of size k.
	// g[k] = G_k / k!, where G_k is its weighted total madness.
	f := make([]int64, m+1)
	g := make([]int64, m+1)
	f[0] = 1

	for k := 1; k <= m; k++ {
		var sumF, sumG, sumCost int64

		for x := 0; x < k; x++ {
			y := k - 1 - x

			sumF = (sumF + f[x]*f[y]) % mod
			sumG = (sumG + g[x]*f[y]) % mod

			v := tri[x] * f[x] % mod
			sumCost = (sumCost + v*f[y]) % mod
		}

		f[k] = int64(k+1) * sumF % mod * inv[k] % mod

		termG := 2 * int64(k+1) % mod * sumG % mod
		termCost := 2 * sumCost % mod
		g[k] = (termG + termCost) % mod * inv[k] % mod
	}

	q := n - m + 1
	s := q - 1

	// A(z) = sum f[k]z^k satisfies A = exp(2zA).
	// h[k] is the coefficient of A(z)^s.
	h := make([]int64, m+1)
	h[0] = 1

	if s > 0 {
		pow2 := int64(1)
		for k := 1; k <= m; k++ {
			pow2 = pow2 * 2 % mod
			base := int64(k + s)
			h[k] = pow2 * int64(s) % mod
			h[k] = h[k] * modPow(base, int64(k-1)) % mod
			h[k] = h[k] * invFact[k] % mod
		}
	}

	var coefficient int64
	for i := 0; i <= m; i++ {
		coefficient = (coefficient + g[i]*h[m-i]) % mod
	}

	answer := fact[m] * int64(q) % mod
	answer = answer * coefficient % mod

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, answer)
	out.Flush()
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n, m int
	var mod int64
	fmt.Fscan(in, &n, &m, &mod)

	inv := make([]int64, m+1)
	if m >= 1 {
		inv[1] = 1
	}
	for i := 2; i <= m; i++ {
		inv[i] = (mod - (mod/int64(i))*inv[mod%int64(i)]%mod) % mod
	}

	// b[k] = B[k] / k!, where B[k] is the weighted count for one block.
	// c[k] = C[k] / k!, where C[k] is its total madness.
	b := make([]int64, m+1)
	c := make([]int64, m+1)
	b[0] = 1

	for k := 1; k <= m; k++ {
		var sumB, sumC, sumQ int64

		for l := 0; l < k; l++ {
			r := k - 1 - l

			prod := b[l] * b[r] % mod
			sumB += prod
			if sumB >= mod {
				sumB -= mod
			}

			partC := (c[l]*b[r] + b[l]*c[r]) % mod
			sumC += partC
			if sumC >= mod {
				sumC -= mod
			}

			leftMad := int64(l*(l+1)) / 2
			rightMad := int64(r*(r+1)) / 2
			q := (leftMad + rightMad) % mod

			sumQ += q * prod % mod
			if sumQ >= mod {
				sumQ -= mod
			}
		}

		factor := int64(k+1) % mod
		b[k] = factor * sumB % mod * inv[k] % mod
		c[k] = (factor*sumC%mod + sumQ) % mod * inv[k] % mod
	}

	maxBlocks := m
	availableGaps := n - m + 1
	if availableGaps < maxBlocks {
		maxBlocks = availableGaps
	}

	prevW := make([]int64, m+1)
	prevD := make([]int64, m+1)
	prevW[0] = 1

	var normalizedAnswer int64
	choose := int64(1)

	for blocks := 1; blocks <= maxBlocks; blocks++ {
		choose = choose * int64(availableGaps-blocks+1) % mod
		choose = choose * inv[blocks] % mod

		curW := make([]int64, m+1)
		curD := make([]int64, m+1)

		for total := blocks; total <= m; total++ {
			maxLast := total - blocks + 1
			var ways, madness int64

			for last := 1; last <= maxLast; last++ {
				remaining := total - last

				addWays := prevW[remaining] * b[last] % mod
				ways += addWays
				if ways >= mod {
					ways -= mod
				}

				addMadness := (prevD[remaining]*b[last] +
					prevW[remaining]*c[last]) % mod
				madness += addMadness
				if madness >= mod {
					madness -= mod
				}
			}

			curW[total] = ways
			curD[total] = madness
		}

		normalizedAnswer += choose * curD[m] % mod
		if normalizedAnswer >= mod {
			normalizedAnswer -= mod
		}

		prevW, prevD = curW, curD
	}

	factorial := int64(1)
	for i := 2; i <= m; i++ {
		factorial = factorial * int64(i) % mod
	}

	answer := normalizedAnswer * factorial % mod

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	fmt.Fprintln(out, answer)
	out.Flush()
}
